-- One-time update: lets reception and manager save the dental materials stock list.
alter table public.clinic_lists drop constraint if exists clinic_lists_kind_check;
alter table public.clinic_lists add constraint clinic_lists_kind_check check (kind in ('dis','proc','fin','stock'));
drop policy if exists lists_insert on public.clinic_lists;
drop policy if exists lists_update on public.clinic_lists;
drop policy if exists lists_delete on public.clinic_lists;
create policy lists_insert on public.clinic_lists for insert with check ((select private.my_role())='admin' or (kind not in ('fin','stock') and (select private.my_role()) in ('manager','doctor') and clinic=(select private.my_clinic())) or (kind='stock' and (select private.my_role()) in ('manager','reception') and clinic=(select private.my_clinic())) or (kind='fin' and (select private.my_role())='manager' and clinic=(select private.my_clinic())));
create policy lists_update on public.clinic_lists for update using ((select private.my_role())='admin' or (kind not in ('fin','stock') and (select private.my_role()) in ('manager','doctor') and clinic=(select private.my_clinic())) or (kind='stock' and (select private.my_role()) in ('manager','reception') and clinic=(select private.my_clinic())) or (kind='fin' and (select private.my_role())='manager' and clinic=(select private.my_clinic()))) with check ((select private.my_role())='admin' or (kind not in ('fin','stock') and (select private.my_role()) in ('manager','doctor') and clinic=(select private.my_clinic())) or (kind='stock' and (select private.my_role()) in ('manager','reception') and clinic=(select private.my_clinic())) or (kind='fin' and (select private.my_role())='manager' and clinic=(select private.my_clinic())));
create policy lists_delete on public.clinic_lists for delete using ((select private.my_role())='admin' or (kind not in ('fin','stock') and (select private.my_role()) in ('manager','doctor') and clinic=(select private.my_clinic())) or (kind='stock' and (select private.my_role()) in ('manager','reception') and clinic=(select private.my_clinic())) or (kind='fin' and (select private.my_role())='manager' and clinic=(select private.my_clinic())));
